entries[295999] = { ["name"] = "Ätzendes Delirium", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht kontinuierlich alle 1 Sek. 249 Schattenschaden, solange sich ein Spielercharakter in dem Bereich aufhält. Der Schaden nimmt zu, je länger Spielercharaktere sich im Effektbereich aufhalten.\n\nWenn ein Spielercharakter fünf Stapel dieses Effekts erhält, wird er in das Reich des Deliriums befördert und ' Ätzendes Delirium ' wird entfernt." }
