entries[296018] = { ["name"] = "Manischer Schrecken", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nEntfesselt einen Psychoschlag, der zufällige Gegner in Angst und Schrecken versetzt und 10 Sek. lang alle 1 Sek. 747 Schattenschaden verursacht.\n\nNach Ablauf des Effekts erleiden alle Ziele sofort 7470 Schattenschaden und die Position des Ziels wird markiert. Wenige Sekunden danach erleiden Gegner innerhalb von 7 Metern um diese Position 16144 Schattenschaden.\n\nHinterlässt einen Bereich von 'Ätzendes Delirium' an dieser Position." }
